const state = {
  fleets:[],
  reports:[],
  transactions:[],
  attendance:[],
  team:[],
  fuels:[],
  payroll:[],
  leaveRequests:[],
  cashAdvances:[],
  attendanceZone:null
};
const status = (label, type) => `<span class="status ${type}">${label}</span>`;
const escapeHtml=value=>String(value??'').replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const parseRupiah=value=>Number(String(value??'').replace(/[^0-9]/g,''))||0;
function formatRupiahInput(input){const digits=String(input.value??'').replace(/[^0-9]/g,'');input.value=digits?Number(digits).toLocaleString('id-ID'):''}
function jakartaDate(value=new Date()){const parts=new Intl.DateTimeFormat('en-US',{timeZone:'Asia/Jakarta',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(value),date=Object.fromEntries(parts.filter(part=>part.type!=='literal').map(part=>[part.type,part.value]));return `${date.year}-${date.month}-${date.day}`}
const dateInputToWibTimestamp=date=>`${date}T12:00:00+07:00`;
const internalAuthEmail=id=>`${String(id).trim().toLowerCase()}@accounts.hma.internal`;
let adminRole='';
const isSuperAdmin=()=>adminRole==='admin';
document.getElementById('todayButton').textContent=`${new Date().toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'})} ▾`;
const attendanceKey='hma_attendance_records_v2';
const fallbackAttendance=[];
function attendanceRecords(){try{return JSON.parse(localStorage.getItem(attendanceKey))||fallbackAttendance}catch{return fallbackAttendance}}
function workdays(employee,period='2026-08'){return attendanceRecords().filter(x=>x.employee===employee&&x.status==='Hadir'&&x.date.startsWith(period)).length}
function tableRows(items, template, target){const columns={reportRows:9,transactionRows:6,attendanceRows:8,teamRows:6,fuelRows:12,payrollRows:6,leaveRequestRows:6,cashAdvanceRows:5};const body=document.querySelector(target);body.innerHTML=items.length?items.map(template).join(''):`<tr><td colspan="${columns[body.id]||1}" style="text-align:center;padding:32px;color:#789">Belum ada data operasional.</td></tr>`}
async function loadFuelReports(){if(!window.hmaSupabase)return;let query=window.hmaSupabase.from('fuel_logs').select('id,filled_at,previous_odometer,current_odometer,distance_km,expected_liters,liters,price_per_liter,fuel_type,validation_status,validation_note,vehicles(plate_no),employee_profile:profiles!fuel_logs_employee_id_fkey(full_name)').order('filled_at',{ascending:false});const from=document.getElementById('fuelFrom')?.value,to=document.getElementById('fuelTo')?.value;if(from)query=query.gte('filled_at',dateInputToWibTimestamp(from));if(to)query=query.lte('filled_at',`${to}T23:59:59+07:00`);const {data,error}=await query.limit(500);if(error){console.warn('Fuel refresh failed:',error.message);notify(error.message||'Data BBM belum dapat dimuat.');return}const rows=data||[],setText=(id,value)=>{const el=document.getElementById(id);if(el)el.textContent=value},total=key=>rows.reduce((sum,row)=>sum+Number(row[key]||0),0),currency=value=>`Rp ${Number(value||0).toLocaleString('id-ID')}`;setText('fuelDistanceTotal',`${total('distance_km').toLocaleString('id-ID')} KM`);setText('fuelExpectedTotal',`${total('expected_liters').toLocaleString('id-ID',{maximumFractionDigits:2})} L`);setText('fuelActualTotal',currency(rows.reduce((sum,row)=>sum+Number(row.liters||0)*Number(row.price_per_liter||0),0)));state.fuels=rows.map(row=>{const expected=Number(row.expected_liters),actual=Number(row.liters),price=Number(row.price_per_liter||0),difference=actual-expected,estimatedCost=expected*price,actualCost=actual*price,costDifference=actualCost-estimatedCost,validation=row.validation_status||'submitted',needsValidation=validation==='submitted'&&(Math.abs(difference)>0.5||Math.abs(costDifference)>5000),label=validation==='verified'?'Tervalidasi':validation==='rejected'?'Ditolak':needsValidation?'Perlu pemeriksaan':'Menunggu pemeriksaan',type=validation==='verified'?'done':validation==='rejected'?'service':'pending';return {id:row.id,date:row.filled_at,displayDate:new Date(row.filled_at).toLocaleDateString('id-ID',{day:'2-digit',month:'short',year:'numeric'}),plate:row.vehicles?.plate_no||'—',employee:row.employee_profile?.full_name||'—',previous:Number(row.previous_odometer||0),current:Number(row.current_odometer||0),distance:Number(row.distance_km||0),expected,liters:actual,price,fuel_type:row.fuel_type||'—',difference,estimatedCost,actualCost,costDifference,validation,label,type,note:row.validation_note||''}});setText('fuelPendingCount',state.fuels.filter(row=>row.validation==='submitted').length.toLocaleString('id-ID'));render()}
function visibleFuelRows(){const term=(document.getElementById('fuelSearch')?.value||'').trim().toLowerCase(),filterStatus=document.getElementById('fuelStatus')?.value||'';return state.fuels.filter(row=>(!filterStatus||row.validation===filterStatus)&&(!term||`${row.plate} ${row.employee} ${row.fuel_type} ${row.label}`.toLowerCase().includes(term)))}
function populateEmployeeOptions(rows){const options=(rows||[]).map(row=>`<option value="${escapeHtml(row.id)}">${escapeHtml(row.employee_code||'—')} · ${escapeHtml(row.full_name)}</option>`).join('');['salaryEmployee','transactionEmployee','fuelEmployee','reportDriver'].forEach(id=>{const select=document.getElementById(id);if(!select)return;const selected=select.value,placeholder=id==='transactionEmployee'?'Tidak terkait karyawan':'Pilih karyawan';select.innerHTML=`<option value="">${placeholder}</option>${options}`;if(selected)select.value=selected})}
async function loadTeam(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('profiles').select('id,employee_code,full_name,position,role').order('employee_code');if(error)return;populateEmployeeOptions((data||[]).filter(row=>row.role==='employee'));const roleLabel={employee:'Karyawan',hr:'HR',finance:'Finance',admin:'Super Admin'};state.team=(data||[]).map(row=>[row.id,row.employee_code||'—',row.full_name,row.position||'—',roleLabel[row.role]||'Karyawan','Aktif','done',row.role]);render()}
async function loadAttendance(){if(!window.hmaSupabase)return;let {data,error}=await window.hmaSupabase.rpc('admin_attendance_records');if(error){console.warn('Admin attendance RPC failed:',error.message);({data,error}=await window.hmaSupabase.from('attendance').select('id,check_in_at,check_out_at,check_in_date,verification_status,note,check_in_zone_distance_meters,profiles(full_name,position)').order('check_in_date',{ascending:false}).limit(500))}if(error){console.warn('Admin attendance refresh failed:',error.message);return}const labels={submitted:['Hadir','pending'],verified:['Terverifikasi','done'],rejected:['Ditolak','service']};state.attendance=(data||[]).map(row=>{const info=labels[row.verification_status]||['Hadir','pending'],arrival=new Date(row.check_in_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}),departure=row.check_out_at?new Date(row.check_out_at).toLocaleTimeString('id-ID',{hour:'2-digit',minute:'2-digit'}):'Belum pulang',distance=Number.isFinite(Number(row.check_in_zone_distance_meters))?`Lokasi tervalidasi · jarak zona ${Math.round(Number(row.check_in_zone_distance_meters))} m`:'Lokasi tervalidasi';return{id:row.id,name:row.full_name||row.profiles?.full_name||'—',position:row.employee_position||row.profiles?.position||'Karyawan',date:row.check_in_date,arrival,departure,label:info[0],note:row.note||distance,type:info[1],checkIn:row.check_in_at,checkOut:row.check_out_at,status:row.verification_status||'submitted'}});render()}
async function loadAttendanceZone(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('attendance_zones').select('id,name,latitude,longitude,radius_meters,is_active').eq('is_active',true).order('created_at',{ascending:true}).limit(1).maybeSingle();if(error)return;state.attendanceZone=data||null;renderAttendanceZone()}
function renderAttendanceZone(){const zone=state.attendanceZone,fields={attendanceZoneId:zone?.id||'',attendanceZoneName:zone?.name||'',attendanceZoneLatitude:zone?.latitude||'',attendanceZoneLongitude:zone?.longitude||'',attendanceZoneRadius:zone?.radius_meters||'',attendanceZoneActive:String(zone?.is_active??true)};Object.entries(fields).forEach(([id,value])=>{const el=document.getElementById(id);if(el)el.value=value});const summary=document.getElementById('attendanceZoneSummary');if(summary)summary.textContent=zone?`${zone.name} · radius ${Number(zone.radius_meters).toLocaleString('id-ID')} m`:'Belum ada zona aktif'}
const parseCoordinate=value=>{const normalized=String(value??'').trim().replace(/\s/g,'').replace(',', '.');return /^-?\d+(?:\.\d+)?$/.test(normalized)?Number(normalized):NaN};
async function saveAttendanceZone(event){event.preventDefault();if(!await ensureAdminSession()){openAdminLogin();return}const submit=event.currentTarget.querySelector('[type="submit"]'),id=document.getElementById('attendanceZoneId').value,payload={name:document.getElementById('attendanceZoneName').value.trim(),latitude:parseCoordinate(document.getElementById('attendanceZoneLatitude').value),longitude:parseCoordinate(document.getElementById('attendanceZoneLongitude').value),radius_meters:Number(document.getElementById('attendanceZoneRadius').value),is_active:document.getElementById('attendanceZoneActive').value==='true'};if(!payload.name||!Number.isFinite(payload.latitude)||!Number.isFinite(payload.longitude)||payload.latitude<-90||payload.latitude>90||payload.longitude<-180||payload.longitude>180||payload.radius_meters<50){notify('Masukkan koordinat valid. Koma atau titik dapat digunakan; radius minimal 50 meter.');return}submit.disabled=true;submit.textContent='Menyimpan…';try{if(payload.is_active){const {error:deactivateError}=await window.hmaSupabase.from('attendance_zones').update({is_active:false,updated_at:new Date().toISOString()}).eq('is_active',true).neq('id',id||'00000000-0000-0000-0000-000000000000');if(deactivateError)throw deactivateError}const query=id?window.hmaSupabase.from('attendance_zones').update({...payload,updated_at:new Date().toISOString()}).eq('id',id):window.hmaSupabase.from('attendance_zones').insert(payload);const {error}=await query;if(error)throw error;await loadAttendanceZone();notify('✓ Zona absensi berhasil disimpan dan langsung aktif.')}catch(error){notify(error.message||'Zona absensi belum dapat disimpan.')}finally{submit.disabled=false;submit.textContent='Simpan zona absensi'}}
async function loadFleets(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('vehicles').select('id,plate_no,model,status,current_odometer').order('plate_no');if(error)return;const labels={active:['Siap operasi','done'],maintenance:['Dalam perawatan','pending'],inactive:['Tidak aktif','service']};state.fleets=(data||[]).map(row=>{const info=labels[row.status]||['Tidak diketahui','pending'];return Object.assign([row.plate_no,row.model||'—','—',info[0],info[1]],{id:row.id,plate:row.plate_no,model:row.model||'—',odometer:Number(row.current_odometer||0),status:row.status,label:info[0],type:info[1]})});const select=document.getElementById('fuelVehicle');if(select){const selected=select.value;select.innerHTML=`<option value="">Pilih kendaraan</option>${(data||[]).filter(row=>row.status==='active').map(row=>`<option value="${escapeHtml(row.id)}" data-odometer="${Number(row.current_odometer||0)}">${escapeHtml(row.plate_no)} · ${escapeHtml(row.model||'Armada')}</option>`).join('')}`;if(selected)select.value=selected}render()}
function reportStatus(value){return {submitted:['Perlu ditinjau','pending'],reviewed:['Sudah ditinjau','done'],rejected:['Ditolak','service']}[value]||[value,'pending']}
async function loadReports(){if(!window.hmaSupabase)return;let query=window.hmaSupabase.from('employee_reports').select('id,report_date,title,description,status,success_count,failed_count,cod_amount,dfod_amount,evidence_path,profiles(full_name,employee_code)').order('report_date',{ascending:false}).order('created_at',{ascending:false});const from=document.getElementById('reportFrom')?.value,to=document.getElementById('reportTo')?.value;if(from)query=query.gte('report_date',from);if(to)query=query.lte('report_date',to);const {data,error}=await query;if(error){notify(error.code==='42501'?'Akses laporan belum diaktifkan di server.':error.message);return}state.reports=await Promise.all((data||[]).map(async row=>{let evidenceUrl='';if(row.evidence_path){const signed=await window.hmaSupabase.storage.from('report-evidence').createSignedUrl(row.evidence_path,3600);evidenceUrl=signed.data?.signedUrl||''}return{id:row.id,date:row.report_date,name:row.profiles?.full_name||'—',code:row.profiles?.employee_code||'—',description:row.description,status:row.status,success:Number(row.success_count||0),failed:Number(row.failed_count||0),cod:Number(row.cod_amount||0),dfod:Number(row.dfod_amount||0),evidenceUrl}}));const sum=key=>state.reports.reduce((total,row)=>total+row[key],0),currency=value=>`Rp ${value.toLocaleString('id-ID')}`;document.getElementById('reportSuccessTotal').textContent=sum('success').toLocaleString('id-ID');document.getElementById('reportFailedTotal').textContent=sum('failed').toLocaleString('id-ID');document.getElementById('reportCodTotal').textContent=currency(sum('cod'));document.getElementById('reportDfodTotal').textContent=currency(sum('dfod'));render()}
async function loadTransactions(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('cash_transactions').select('id,transaction_date,type,category,description,amount').order('transaction_date',{ascending:false}).order('created_at',{ascending:false}).limit(250);if(error){if(error.code!=='42501')notify(error.message);return}state.transactions=(data||[]).map(row=>({id:row.id,date:row.transaction_date,type:row.type,category:row.category,description:row.description||'—',amount:Number(row.amount||0)}));const now=new Date(),monthPrefix=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`,monthRows=state.transactions.filter(row=>row.date.startsWith(monthPrefix)),income=monthRows.filter(row=>row.type==='income').reduce((sum,row)=>sum+row.amount,0),expense=monthRows.filter(row=>row.type==='expense').reduce((sum,row)=>sum+row.amount,0),currency=value=>`Rp ${value.toLocaleString('id-ID')}`;document.getElementById('transactionIncomeTotal').textContent=currency(income);document.getElementById('transactionExpenseTotal').textContent=currency(expense);document.getElementById('transactionNetTotal').textContent=currency(income-expense);render()}
async function loadPayroll(){if(!window.hmaSupabase)return;const {data,error}=await window.hmaSupabase.from('payroll_records').select('id,period_start,period_end,work_days,base_salary,allowance,deduction,net_salary,payment_status,created_at,profiles(full_name,employee_code)').order('period_start',{ascending:false}).order('created_at',{ascending:false});if(error){if(error.code!=='42501')notify(error.message);return}state.payroll=(data||[]).map(row=>({id:row.id,name:row.profiles?.full_name||'—',code:row.profiles?.employee_code||'—',periodStart:row.period_start,createdAt:row.created_at,workDays:Number(row.work_days||0),netSalary:Number(row.net_salary||0),paymentStatus:row.payment_status}));render()}
