async function updateSalaryWorkdays(){const employeeId=document.getElementById('salaryEmployee').value,period=document.getElementById('salaryPeriod').value,field=document.getElementById('salaryWorkdays');if(!employeeId||!period){currentPayrollWorkdays=0;field.value='Pilih karyawan dan periode';return}const start=`${period}-01`,end=`${period}-${String(new Date(Number(period.slice(0,4)),Number(period.slice(5,7)),0).getDate()).padStart(2,'0')}`;field.value='Menghitung dari absensi…';try{const {count,error}=await window.hmaSupabase.from('attendance').select('id',{count:'exact',head:true}).eq('employee_id',employeeId).gte('check_in_date',start).lte('check_in_date',end).neq('verification_status','rejected');if(error)throw error;currentPayrollWorkdays=count||0;field.value=`${currentPayrollWorkdays} hari kerja dari absensi`}catch(error){currentPayrollWorkdays=0;field.value='Absensi belum dapat dihitung'}}
