function downloadImportTemplate(){if(!window.XLSX){notify('Modul Excel belum termuat. Muat ulang halaman.');return}const type=document.getElementById('importType').value||'transaction';const templates={transaction:{sheet:'Arus Kas',rows:[{tanggal:'2026-09-12',jenis:'keluar',kategori:'Biaya BBM Operasional',keterangan:'Contoh pengisian BBM',nominal:150000,id_karyawan:''},{tanggal:'2026-09-12',jenis:'masuk',kategori:'Payable COD Fee',keterangan:'Contoh penerimaan COD',nominal:250000,id_karyawan:''}]},fleet:{sheet:'Armada',rows:[{plat_nomor:'B 1234 HMA',jenis_model:'Blindvan',odometer:0,status:'aktif'}]},employee:{sheet:'Karyawan',rows:[{nama_lengkap:'Contoh Nama Karyawan',jabatan:'Driver',kata_sandi_awal:'minimal8karakter',role:'employee'}]}};const data=templates[type]||templates.transaction,worksheet=XLSX.utils.json_to_sheet(data.rows),workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,worksheet,data.sheet);XLSX.writeFile(workbook,`template-${type}-hma.xlsx`);notify('Template Excel berhasil diunduh.');}
