async function readImportRows(file,type){if(!window.XLSX)throw new Error('Modul pembaca Excel belum termuat.');const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'}),preferred=type==='employee'?'Karyawan':type==='transaction'?'Arus Kas':'Armada',sheet=workbook.Sheets[preferred]||workbook.Sheets[workbook.SheetNames[0]],firstColumn=type==='employee'?'nama_lengkap':type==='transaction'?'tanggal':'plat_nomor';return XLSX.utils.sheet_to_json(sheet,{defval:''}).filter(row=>{const first=String(row[firstColumn]).trim();return first&&!/^contoh/i.test(first)})}
async function importEmployees(rows,session){const results=[];for(let index=0;index<rows.length;index++){const row=rows[index],fullName=String(row.nama_lengkap||'').trim(),position=String(row.jabatan||'').trim(),password=String(row.kata_sandi_awal||'');if(!fullName||!position||password.length<8){results.push({ok:false,row:index+2,error:'Nama, jabatan, dan kata sandi minimal 8 karakter wajib diisi.'});continue}const {data,error}=await window.hmaSupabase.functions.invoke('create-employee',{body:{fullName,position,password},headers:{Authorization:`Bearer ${session.access_token}`}});if(error){let message='Gagal membuat akun.';try{message=(await error.context.json()).error||message}catch{}results.push({ok:false,row:index+2,error:message})}else results.push({ok:true,row:index+2,code:data.employeeCode})}return results}
async function importFleets(rows){const aliases={'siap operasi':'active','aktif':'active','dalam perawatan':'maintenance','perawatan':'maintenance','tidak aktif':'inactive'};const valid=['active','maintenance','inactive'],payload=[],errors=[];rows.forEach((row,index)=>{const plate=String(row.plat_nomor||'').trim().toUpperCase().replace(/\s+/g,' '),model=String(row.jenis_model||'').trim(),raw=String(row.status||'active').trim().toLowerCase(),fleetStatus=aliases[raw]||raw,odometer=Number(row.odometer)||0;if(!plate||!model||!valid.includes(fleetStatus)||odometer<0)errors.push({ok:false,row:index+2,error:'Plat, model, odometer, atau status tidak valid.'});else payload.push({plate_no:plate,model,current_odometer:odometer,status:fleetStatus})});if(payload.length){const {data,error}=await window.hmaSupabase.from('vehicles').upsert(payload,{onConflict:'plate_no'}).select('plate_no');if(error)throw error;(data||[]).forEach(item=>errors.push({ok:true,plate:item.plate_no}))}return errors}
async function importTransactions(rows){const results=[];for(let index=0;index<rows.length;index++){const row=rows[index],date=String(row.tanggal||'').trim(),rawType=String(row.jenis||'').trim().toLowerCase(),type=['masuk','income','uang masuk'].includes(rawType)?'income':['keluar','expense','uang keluar'].includes(rawType)?'expense':'',category=String(row.kategori||'').trim(),description=String(row.keterangan||'').trim(),amount=parseRupiah(String(row.nominal||'')),employeeId=String(row.id_karyawan||'').trim()||null;if(!/^\d{4}-\d{2}-\d{2}$/.test(date)||!type||!category||!description||amount<1){results.push({ok:false,row:index+2,error:'Tanggal, jenis, kategori, keterangan, atau nominal tidak valid.'});continue}const {error}=await window.hmaSupabase.rpc('record_cash_transaction',{p_transaction_date:date,p_type:type,p_category:category,p_description:description,p_amount:amount,p_employee_id:employeeId});if(error)results.push({ok:false,row:index+2,error:error.message});else results.push({ok:true,row:index+2})}return results}
document.getElementById('importForm').addEventListener('submit',async e=>{e.preventDefault();const submit=e.currentTarget.querySelector('[type="submit"]');submit.disabled=true;submit.textContent='Mengimpor…';importFeedback.hidden=true;try{if(!await ensureAdminSession())throw new Error('Sesi admin berakhir. Silakan masuk kembali.');const type=document.getElementById('importType').value,rows=await readImportRows(document.getElementById('importFile').files[0],type);if(!rows.length)throw new Error('Tidak ada baris data yang dapat diimpor.');const {data:{session}}=await window.hmaSupabase.auth.getSession();const results=type==='employee'?await importEmployees(rows,session):type==='transaction'?await importTransactions(rows):await importFleets(rows),success=results.filter(x=>x.ok).length,failed=results.length-success;if(type==='employee')await loadTeam();else if(type==='transaction')await loadTransactions();else await loadFleets();importFeedback.textContent=`Selesai: ${success} berhasil, ${failed} gagal.${failed?' Periksa format pada baris '+results.filter(x=>!x.ok).map(x=>x.row).join(', ')+'.':''}`;importFeedback.style.background=failed?'#fff5e2':'#edf8f7';importFeedback.style.color=failed?'#9a6200':'#087c74';importFeedback.hidden=false;if(!failed){setTimeout(closeImportModal,1400);notify(`✓ ${success} data berhasil diimpor.`)}}catch(error){importFeedback.textContent=error.code==='42501'?'Izin import belum aktif untuk akun ini.':(error.message||'Import data gagal.');importFeedback.style.background='#fff0f0';importFeedback.style.color='#c33';importFeedback.hidden=false}finally{submit.disabled=false;submit.textContent='Mulai import'}});
