function downloadHrWorkbook(kind){if(!window.XLSX){notify('Modul Excel belum termuat. Muat ulang halaman.');return}const isAttendance=kind==='attendance',items=isAttendance?state.attendance.filter(x=>(!document.getElementById('attendanceFrom').value||x.date>=document.getElementById('attendanceFrom').value)&&(!document.getElementById('attendanceTo').value||x.date<=document.getElementById('attendanceTo').value)):visibleFuelRows();if(!items.length){notify('Tidak ada data pada periode yang dipilih.');return}const rows=isAttendance?items.map(x=>({'Tanggal':x.date,'Nama karyawan':x.name,'Jabatan':x.position,'Jam masuk':x.arrival,'Jam pulang':x.departure,'Status':x.label,'Catatan':x.note})):items.map(x=>({'Tanggal':x.date,'Kendaraan':x.plate,'Karyawan':x.employee,'KM sebelumnya':x.previous,'KM saat isi':x.current,'Jarak KM':x.distance,'Jenis BBM':x.fuel_type||'—','Estimasi liter':x.expected,'Liter realisasi':x.liters,'Harga per liter':x.price,'Estimasi biaya':x.estimatedCost,'Realisasi biaya':x.actualCost,'Selisih biaya':x.costDifference,'Status validasi':x.label,'Catatan validasi':x.note}));const summary=XLSX.utils.aoa_to_sheet([[isAttendance?'REKAP ABSENSI KARYAWAN':'REKAP VALIDASI BBM'],['Dicetak',new Date().toLocaleString('id-ID')],['Jumlah data',rows.length]]),detail=XLSX.utils.json_to_sheet(rows),workbook=XLSX.utils.book_new();XLSX.utils.book_append_sheet(workbook,summary,'Ringkasan');XLSX.utils.book_append_sheet(workbook,detail,'Detail');XLSX.writeFile(workbook,`${isAttendance?'rekap-absensi':'rekap-validasi-bbm'}-${jakartaDate()}.xlsx`);notify('Report Excel berhasil diunduh.');}
