document.querySelectorAll('button').forEach(button=>{if(button.matches('[data-view],[data-action],[data-open-modal],[data-open-import],[data-close-import],[data-close-modal],[data-close-report],[data-close-fuel],[data-close-fuel-type],[data-close-fuel-price],[data-close-fleet],[data-close-salary],[data-close-employee],[data-close-employee-reset],[data-close-admin-login],#pullReports,#downloadReport,#fuelRefresh,#transactionRefresh,#attendanceRefresh,#payrollRefresh')||button.type==='submit')return;button.addEventListener('click',()=>{const label=button.textContent.trim();if(quickRoutes[label]){document.querySelector(`[data-view="${quickRoutes[label]}"]`).click();return}if(label.includes('Pusat Bantuan')){notify('Pusat bantuan: hubungi administrator operasional.');return}if(label==='⋮'||label.includes('Notifikasi')){notify('Tidak ada pembaruan baru.')}})});
backdrop.addEventListener('click',()=>{if(reportModal.open)closeReportModal();if(fuelModal.open)closeFuelModal();if(fuelReviewModal.open)closeFuelReview();if(attendanceReviewModal.open)closeAttendanceReview();if(fleetModal.open)closeFleetModal();if(fuelTypeModal.open)closeFuelTypeModal();if(fuelPriceModal.open)closeFuelPriceModal();if(fuelMasterModal.open)closeFuelMasterModal();if(salaryModal.open)closeSalaryModal();if(employeeModal.open)closeEmployeeModal();if(employeeResetModal.open)closeEmployeeReset();if(employeeEditModal.open)closeEmployeeEdit();if(importModal.open)closeImportModal();if(passwordRecoveryModal.open)passwordRecoveryModal.close();if(adminLoginModal.open)closeAdminLogin()});setDefaultReportDates();render();refreshAdminIdentity();if(window.hmaSupabase)window.hmaSupabase.auth.onAuthStateChange((event)=>{if(event==='PASSWORD_RECOVERY')setTimeout(openPasswordRecovery,0);if(event==='SIGNED_OUT')setTimeout(returnToLogin,0);setTimeout(refreshAdminIdentity,0);if(event!=='SIGNED_OUT')setTimeout(loadOperationalDataForSession,0)});setTimeout(async()=>{if(!await ensureAdminSession())openAdminLogin();else await loadOperationalDataForSession()},0);
async function loadOperationalDataForSession(){if(!await ensureAdminSession())return;refreshOperationalSummary()}
function refreshOperationalSummary(){loadFuelReports();loadFleets();loadReports();loadTransactions();loadAttendance();loadPayroll();loadTeam();loadEmployeeRequests();loadAttendanceZone()}
if(window.hmaSupabase){window.hmaSupabase.channel('hma-operational-summary').on('postgres_changes',{event:'*',schema:'public',table:'cash_transactions'},loadTransactions).on('postgres_changes',{event:'*',schema:'public',table:'attendance'},loadAttendance).on('postgres_changes',{event:'*',schema:'public',table:'attendance_zones'},loadAttendanceZone).on('postgres_changes',{event:'*',schema:'public',table:'employee_reports'},loadReports).on('postgres_changes',{event:'*',schema:'public',table:'fuel_logs'},loadFuelReports).on('postgres_changes',{event:'*',schema:'public',table:'payroll_records'},loadPayroll).on('postgres_changes',{event:'*',schema:'public',table:'vehicles'},loadFleets).on('postgres_changes',{event:'*',schema:'public',table:'employee_leave_requests'},loadEmployeeRequests).on('postgres_changes',{event:'*',schema:'public',table:'employee_cash_advances'},loadEmployeeRequests).subscribe();setInterval(refreshOperationalSummary,30000)}
